"""One step up the scale ladder: train the 50 nm correction on loops generated by the learned 25 nm
model instead of on 5 nm truth, then roll it out against the truth test loops. Compare with
results/torque_energy_stable_50nm (trained on truth, same recipe).

1. the 25 nm energy model (results/torque_energy_25nm) relaxes whole loops from saturation along the
   train and valid field axes of datasets/shield (no fine simulation);
2. those 25 nm states form datasets/shield_ladder_25nm (Well format, 25 nm cells);
3. train_torque.py trains a 50 nm energy + stability model on it (COARSEN 2 of 25 nm);
4. rollout.py rolls it out on the truth test loops at 50 nm.

    python experiments/overnight/ladder.py
"""

import math
from pathlib import Path

import numpy as np
import torch

import datagen
import rollout
import train
import train_torque
import well_io
from datagen import A, Ms
from model import DemagField, ExchangeField

DATA_DIR = Path("datasets/shield_ladder_25nm")
RUN_DIR = Path("results/overnight/ladder_50nm")
DX_25 = [25e-9] * 3
N_25 = [20, 10, 4]


def generate():
    """Loops of the learned 25 nm model on the train and valid axes, written as a Well dataset."""
    train_torque.ENERGY = True
    model = train_torque.make_model(DX_25)
    model.load_state_dict(torch.load("results/torque_energy_25nm/model.pt", map_location=train.DEVICE))
    model.eval()
    demag_field = DemagField(n=N_25, dx=DX_25, Ms=Ms, device=train.DEVICE)
    exchange_field = ExchangeField(dx=DX_25, A=A, Ms=Ms)

    for split in ("train", "valid"):
        indices = list(datagen.SPLITS[split])
        axes = [datagen.random_axis(np.random.default_rng([datagen.SEED, i])) for i in indices]
        fields = np.stack([datagen.loop(datagen.Hmin, datagen.Hmax, datagen.steps, axis) for axis in axes])
        m0 = torch.tensor(np.stack(axes), dtype=torch.float32, device=train.DEVICE)[:, None, None, None, :]
        m0 = m0.expand(-1, *N_25, -1).contiguous()  # saturated along each axis
        fields_tensor = torch.tensor(fields, dtype=torch.float32, device=train.DEVICE)
        # step 0 must be an equilibrium too (rollout keeps its start as given)
        m0, _ = train.relax(model, demag_field, exchange_field, m0, fields_tensor[:, 0])
        states, converged = rollout.rollout(model, demag_field, exchange_field, m0, fields_tensor)
        print(f"{split}: {len(indices)} loops, converged {converged.float().mean().item():.3f}", flush=True)
        (DATA_DIR / "data" / split).mkdir(parents=True, exist_ok=True)
        for k, i in enumerate(indices):
            well_io.write_well_file(
                DATA_DIR / "data" / split / f"ladder_{i:02d}.hdf5",
                dx=DX_25[0],
                m=states[k : k + 1].cpu().numpy(),
                step_scalars={"Bx": datagen.mu_0 * fields[k : k + 1, :, 0], "By": datagen.mu_0 * fields[k : k + 1, :, 1]},
                trajectory_scalars={"field_angle": [math.atan2(axes[k][1], axes[k][0])]},
                constants={"Ms": Ms, "A": A},
            )


def main():
    if not (DATA_DIR / "data" / "valid").exists():
        generate()

    # train at 50 nm on the 25 nm loops: COARSEN is relative to the stored 25 nm cells
    train.DATASET, train.COARSEN = str(DATA_DIR), 2
    train_torque.DX, train_torque.N = DX_25, N_25
    train_torque.ENERGY, train_torque.STABILITY_WEIGHT = True, 1.0
    train_torque.RUN_DIR = RUN_DIR
    train_torque.main()

    # roll out against the 5 nm truth test loops at 50 nm
    train.DATASET, train.COARSEN = "datasets/shield", 10
    rollout.RUN_DIR = RUN_DIR
    rollout.main()


if __name__ == "__main__":
    main()
